document.addEventListener("DOMContentLoaded",(()=>{document.getElementById("cadastro-form").addEventListener("submit",(e=>{e.preventDefault();const t=document.getElementById("nome").value,o=document.getElementById("email").value,n=document.getElementById("password").value;t&&o&&n?(alert("Cadastro realizado com sucesso!"),window.location.href="/login.html"):alert("Por favor, preencha todos os campos.")}))}));